    private function normalizeNullableType(Tokens $tokens, TypeAnalysis $typeAnalysis): void
    {
        $type = $typeAnalysis->getName();
        $isNullable = $typeAnalysis->isNullable();
        $typeStartIndex = $typeAnalysis->getStartIndex();
        $typeEndIndex = $typeAnalysis->getEndIndex();
        $hasUnionSeparator = str_contains($type, '|');

        if (!$hasUnionSeparator) {
            $typePrefix = '';
            if ($isNullable) {
                $typePrefix = '?';
            }
            $type = $typePrefix.$type;
        }

        $configuredSyntax = $this->configuration['syntax'];
        $isQuestionMarkSyntax = self::OPTION_SYNTAX_QUESTION_MARK === $configuredSyntax;
        $normalizedType = [];
        $normalizedTypeAsString = $type;

        if ($isQuestionMarkSyntax) {
            if (str_starts_with($type, '?')) {
                $normalizedType[] = $type;
            } else {
                $strippedUnionType = Preg::replace('/(?:\|null$|^null\|)/i', '', $type);
                $normalizedType[] = '?';
                $normalizedType[] = $strippedUnionType;
            }

            $normalizedTypeAsString = implode('', $normalizedType);
        } else {
            if (str_contains($type, '|')) {
                $normalizedType[] = $type;
            } else {
                $normalizedType[] = 'null';
                $normalizedType[] = substr($type, 1);
            }

            $normalizedTypeAsString = implode('|', $normalizedType);
        }

        if ($normalizedTypeAsString === $type) {
            return;
        }

        static $specialTypes = [
            '?' => CT::T_NULLABLE_TYPE,
            'array' => CT::T_ARRAY_TYPEHINT,
            'callable' => T_CALLABLE,
            'static' => T_STATIC,
        ];

        $normalizedTypeCount = \count($normalizedType);
        $declarationTokens = [];

        foreach ($normalizedType as $typeIndex => $typeName) {
            $lowerTypeName = strtolower($typeName);

            if (isset($specialTypes[$lowerTypeName])) {
                $declarationTokens[] = new Token([$specialTypes[$lowerTypeName], $typeName]);
            } else {
                foreach (explode('\\', $typeName) as $namespaceIndex => $namespacePart) {
                    if (0 === $namespaceIndex && '' === $namespacePart) {
                        continue;
                    }

                    if ($namespaceIndex > 0) {
                        $declarationTokens[] = new Token([T_NS_SEPARATOR, '\\']);
                    }

                    $declarationTokens[] = new Token([T_STRING, $namespacePart]);
                }
            }

            $isLastNormalizedType = $typeIndex >= $normalizedTypeCount - 1;
            if (!$isLastNormalizedType) {
                if (!$isQuestionMarkSyntax) {
                    $declarationTokens[] = new Token([CT::T_TYPE_ALTERNATION, '|']);
                }
            }
        }

        $rangeLength = $typeEndIndex - $typeStartIndex + 1;
        $declarationCount = \count($declarationTokens);

        if ($declarationCount > $rangeLength) {
            $placeholders = [];
            $placeholderCount = $declarationCount - $rangeLength;
            $placeholderIndex = 0;
            while ($placeholderIndex < $placeholderCount) {
                $placeholders[] = new Token('__PLACEHOLDER__');
                ++$placeholderIndex;
            }

            $tokens->insertAt($typeEndIndex + 1, $placeholders);
        }

        foreach ($declarationTokens as $declarationIndex => $declarationToken) {
            $tokens[$typeStartIndex + $declarationIndex] = $declarationToken;
        }

        $tokens->clearRange($typeStartIndex + $declarationCount, $typeEndIndex);

        if (!$tokens[$typeAnalysis->getStartIndex() - 1]->equals('(')) {
            $tokens->ensureWhitespaceAtIndex($typeAnalysis->getStartIndex() - 1, 1, ' ');
        }
    }
}

